import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse('{"title":"Documentation site","description":"","frontmatter":{},"headers":[],"relativePath":"records/docs-site-episode.md","filePath":"records/docs-site-episode.md"}'),s={name:"records/docs-site-episode.md"};function i(n,e,r,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<div class="warning custom-block"><p class="custom-block-title">Historical record</p><p>This page records what happened on a date, with its observed failures and limits. It is not a requirement for the current implementation. Current behaviour is in <a href="/Rho/docs/reference/status">Status</a>.</p></div><h1 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h1><p>Updated: 2026-11-02.</p><p>Before this pass Rho had no online documentation: the only published surface was the downloads page at <a href="https://yulab-smu.top/Rho/" target="_blank" rel="noreferrer">https://yulab-smu.top/Rho/</a>, and the 49 documents in <code>docs/</code> were readable only through GitHub&#39;s file view. This record covers the site that publishes them, what was checked, and what remains unverified.</p><h2 id="what-existed" tabindex="-1">What existed <a class="header-anchor" href="#what-existed" aria-label="Permalink to &quot;What existed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>What it was</th></tr></thead><tbody><tr><td><code>https://yulab-smu.top/Rho/</code></td><td>The <code>gh-pages</code> branch: a hand-written downloads page, <code>.nojekyll</code> and <code>updates/{stable,development}.json</code> plus <code>updates/tauri/*</code>, the update feeds a 0.4.0 desktop install reads</td></tr><tr><td>npm <code>@rho-workspace/rho</code></td><td>Published, version 0.5.2, but the registry record&#39;s <code>readme</code> field is the literal string <code>ERROR: No README data found!</code>, so the package page shows no description</td></tr><tr><td><code>docs/</code> in the repository</td><td>49 Markdown files, 12,078 lines, with 74 anchored links between them and 37 links that leave the directory for <code>CONTRIBUTING.md</code>, <code>SECURITY.md</code>, <code>protocol/</code>, <code>scripts/</code> and <code>output/</code></td></tr></tbody></table><p>Two statements were stale and are corrected in this pass: <code>README.md</code> said npm publication had not been performed, and nothing said where documentation could be read.</p><h2 id="what-was-built" tabindex="-1">What was built <a class="header-anchor" href="#what-was-built" aria-label="Permalink to &quot;What was built&quot;">​</a></h2><p><code>docs/</code> stays the single source. <code>scripts/docs-site.mjs</code> copies every Markdown file into <code>site/content/&lt;section&gt;/</code>, rewrites its links so they resolve in the site, writes a <code>navigation.json</code> the theme reads, and records in <code>links.json</code> the source file and every rewritten link. A document that matches no section fails the run instead of disappearing from the site.</p><p>The three sections are a reading order, not a storage scheme:</p><ul><li><strong>Concepts</strong> — <code>ARCHITECTURE</code>, <code>COLLABORATION</code>, <code>EXECUTION</code>, <code>TECHSTACK</code>, <code>DEVELOPMENT</code>, <code>ROADMAP</code>, <code>AGENT-ACTIVITY</code>.</li><li><strong>Reference</strong> — <code>HEADLESS</code>, <code>FRONTEND</code>, <code>STATUS</code>, <code>RELEASE</code>, <code>PLUGIN-AUTHORING</code>.</li><li><strong>Records</strong> — 36 episodes, acceptance records and earlier plans, ordered by the <code>Updated:</code> date each one carries and grouped by month in the sidebar. Every record page opens with a banner saying it is a historical record and not a requirement.</li></ul><p>The site is VitePress 1.6.4 with local full-text search. The landing page is an authored Vue component, not a theme preset: it uses the application&#39;s own palette and type from <code>web/theme.css</code> (accent <code>#1e6b52</code>, ink <code>#202927</code>, hairline <code>#e1e6e3</code>, system UI and mono faces, a Georgia display face matching the application&#39;s own ρ mark) and shows five real screenshots of Rho 0.5.2, four of them captured on the bundled PA14 quorum-sensing project.</p><p>The landing page states the version split (npm 0.5.2 against the 0.4.0 installers), names what is checked, what is limited and what is not established, and links to <a href="/Rho/docs/reference/status">Status</a> as the single summary rather than restating it.</p><h2 id="what-was-observed" tabindex="-1">What was observed <a class="header-anchor" href="#what-was-observed" aria-label="Permalink to &quot;What was observed&quot;">​</a></h2><p>Built with <code>npm run docs:build</code>: 55 pages, 5.7 MB, 3–7 s, no dead links reported by VitePress with <code>ignoreDeadLinks: false</code>, and 280 links rewritten across the 49 documents. <code>npm run docs:check</code> compares the generated navigation against <code>docs/</code> and passes.</p><p>Screenshots were taken with Playwright at 1440×900 and 390×834 and read back:</p><ul><li>The landing page renders its hero, screenshots, evidence bands and repository cards at both widths; the phone layout wraps the install command instead of clipping it.</li><li>The documentation pages keep the 690 px measure, the sidebar and the outline; tables in <code>HEADLESS</code> and <code>CI-EPISODE</code> render at full width.</li><li>Search returns <code>HEADLESS</code> § Budgets for &quot;budget&quot;, with the matched table row in the detailed view.</li><li>A record page shows its historical banner above the title and the month grouping in the sidebar.</li></ul><p>Defects found and fixed in this pass, all by looking at the screenshots: VitePress resolves its public directory as <code>&lt;srcDir&gt;/public</code>, so the first build shipped no images or logo (assets moved to <code>site/content/public/</code>); the hero headline wrapped to a one-word line (fixed with two block lines and <code>text-wrap: balance</code>); the feature screenshots at full window width were unreadable at their column size (cropped to the content area, shared 4:3 ratio); record summaries cut mid-clause (now cut at a sentence boundary, date prefix removed).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>No one outside this machine has read the site yet. Nothing here is a usability claim.</li><li>The site is served from <code>gh-pages</code> under <code>/Rho/docs/</code>; the download page, <code>.nojekyll</code> and the four <code>updates/*.json</code> paths are unchanged, so an installed 0.4.0 desktop client keeps its update feed. That preservation is the reason the site was added as a subdirectory instead of replacing the branch root.</li><li>The npm readme cannot be repaired for an already published version; the next publication carries <code>README.md</code>, which the packed candidate already includes.</li><li><code>docs/HEADLESS.md</code> still titles itself &quot;Rho local backend 0.5.1&quot; while the package is 0.5.2. The title is published as written; changing it is a content decision for the owner, not a site one.</li><li>Two documents are withheld from the site: <code>docs/README.md</code> (the site&#39;s own navigation replaces it) and the withdrawn 2026-10-26 design commission under <code>docs/design/</code>, which the repository already treats as history rather than requirements.</li></ul>',20)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
